pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Burnable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/interfaces/IERC2981.sol";

contract WhitelistedRevealNFT is ERC721, ERC721Burnable, Ownable, IERC2981 {
    using Strings for uint256;

    // --- State Variables ---

    // Mapping to store whitelist status and mint limits for addresses
    mapping(address => uint256) private _whitelistMintLimit;
    mapping(address => uint256) private _whitelistMintedCount;

    // Base URI for revealed NFTs
    string private _baseTokenURI;

    // Flag to indicate if the reveal has happened
    bool private _revealed = false;

    // Royalties
    address payable private _royaltyRecipient;
    uint32 private _royaltyBps; // Basis points (e.g., 1000 for 10%)

    // --- Events ---
    event WhitelistMinted(address indexed minter, uint256 indexed tokenId);
    event RevealHappened();
    event RoyaltiesUpdated(address indexed recipient, uint32 bps);

    // --- Constructor ---
    constructor(
        string memory name,
        string memory symbol,
        address payable royaltyRecipient,
        uint32 royaltyBps
    ) ERC721(name, symbol) Ownable(msg.sender) {
        require(royaltyBps <= 10000, "Royalty basis points must be 10000 or less"); // Max 100%
        _royaltyRecipient = royaltyRecipient;
        _royaltyBps = royaltyBps;
    }

    // --- Whitelist Management ---

    /**
     * @notice Adds an address to the whitelist with a specified mint limit.
     * @param _address The address to add to the whitelist.
     * @param _limit The maximum number of NFTs the address can mint.
     */
    function addToWhitelist(address _address, uint256 _limit) external onlyOwner {
        _whitelistMintLimit[_address] = _limit;
    }

    /**
     * @notice Removes an address from the whitelist.
     * @param _address The address to remove from the whitelist.
     */
    function removeFromWhitelist(address _address) external onlyOwner {
        delete _whitelistMintLimit[_address];
        delete _whitelistMintedCount[_address];
    }

    /**
     * @notice Checks if an address is whitelisted and has mints remaining.
     * @param _address The address to check.
     * @return bool True if the address is whitelisted and has mints remaining.
     */
    function isWhitelisted(address _address) public view returns (bool) {
        return _whitelistMintLimit[_address] > _whitelistMintedCount[_address];
    }

    // --- Minting ---

    /**
     * @notice Mints a specified number of NFTs for the caller, if whitelisted.
     * @param _quantity The number of NFTs to mint.
     */
    function mintWhitelisted(uint256 _quantity) external {
        require(_quantity > 0, "Quantity must be greater than 0");
        require(isWhitelisted(msg.sender), "Not whitelisted or no mints remaining");

        uint256 currentMintCount = _whitelistMintedCount[msg.sender];
        uint256 remainingLimit = _whitelistMintLimit[msg.sender] - currentMintCount;

        require(_quantity <= remainingLimit, "Exceeds whitelist mint limit");

        for (uint256 i = 0; i < _quantity; i++) {
            uint256 tokenId = totalSupply() + 1;
            _safeMint(msg.sender, tokenId);
            _whitelistMintedCount[msg.sender]++;
            emit WhitelistMinted(msg.sender, tokenId);
        }
    }

    // --- Reveal Mechanism ---

    /**
     * @notice Sets the base URI for the NFTs. This should be called before revealing.
     * @param _baseTokenURI_ The base URI for token metadata.
     */
    function setBaseTokenURI(string memory _baseTokenURI_) external onlyOwner {
        _baseTokenURI = _baseTokenURI_;
    }

    /**
     * @notice Reveals the NFTs by setting the reveal status.
     * After this, tokenURIs will resolve correctly if _baseTokenURI is set.
     */
    function reveal() external onlyOwner {
        require(!_revealed, "Reveal already happened");
        _revealed = true;
        emit RevealHappened();
    }

    /**
     * @notice Returns the reveal status.
     * @return bool True if the reveal has happened.
     */
    function revealed() public view returns (bool) {
        return _revealed;
    }

    /**
     * @notice Overrides the default tokenURI function to handle pre-reveal and post-reveal.
     * @param tokenId The ID of the token.
     * @return The token URI.
     */
    function tokenURI(uint256 tokenId) public view virtual override returns (string memory) {
        require(_exists(tokenId), "ERC721Metadata: URI query for nonexistent token");

        if (_revealed) {
            // If revealed, use the base URI
            if (bytes(_baseTokenURI).length == 0) {
                // Fallback if base URI is not set even after reveal
                return super.tokenURI(tokenId);
            }
            return string(abi.encodePacked(_baseTokenURI, tokenId.toString()));
        } else {
            // Before reveal, return a placeholder or specific pre-reveal URI
            // For simplicity, we'll return a placeholder indicating it's not revealed.
            // In a real-world scenario, you might have a different logic here.
            return "ipfs://pre-reveal-metadata/"; // Example placeholder
        }
    }

    // --- Royalties (EIP-2981) ---

    /**
     * @notice Sets the royalty recipient and basis points.
     * @param _recipient The address to receive royalties.
     * @param _bps The basis points for royalties.
     */
    function setRoyalties(address payable _recipient, uint32 _bps) external onlyOwner {
        require(_bps <= 10000, "Royalty basis points must be 10000 or less"); // Max 100%
        _royaltyRecipient = _recipient;
        _royaltyBps = _bps;
        emit RoyaltiesUpdated(_recipient, _bps);
    }

    /**
     * @notice Returns the royalty information for a given token.
     * @param tokenId The ID of the token.
     * @param salePrice The sale price of the token.
     * @param royaltyRecipient The address to receive royalties.
     * @param royaltyAmount The amount of royalties to be paid.
     */
    function royaltyInfo(
        uint256 tokenId,
        uint256 salePrice
    )
        external
        view
        override
        returns (address royaltyRecipient, uint256 royaltyAmount)
    {
        // We only apply royalties if the reveal has happened and a recipient is set.
        // This is a design choice; you might want to apply royalties even before reveal.
        if (_revealed && _royaltyRecipient != address(0) && _royaltyBps > 0) {
            royaltyRecipient = _royaltyRecipient;
            royaltyAmount = (salePrice * _royaltyBps) / 10000;
        } else {
            royaltyRecipient = address(0);
            royaltyAmount = 0;
        }
    }

    // --- Owner Functions ---

    /**
     * @notice Transfers ownership of the contract.
     * @param newOwner The address of the new owner.
     */
    function transferOwnership(address newOwner) public virtual override onlyOwner {
        super.transferOwnership(newOwner);
    }

    // --- Fallback / Receive ---
    // Optional: Add receive function if you expect Ether to be sent directly to the contract
    receive() external payable {}
}

