            tokenId: tokenId,
            amount: amount,
            price: price,
            seller: msg.sender,
            active: true
        });

        // Transfer tokens from seller to contract (escrow)
        safeTransferFrom(msg.sender, address(this), tokenId, amount, "");

        emit SaleListed(currentSaleId, tokenId, amount, price, msg.sender);
        nextSaleId++;
