        require(msg.value == sale.price, "Incorrect payment amount");
        require(balanceOf(address(this), sale.tokenId) >= sale.amount, "Contract does not have enough tokens for this sale");

        // Transfer tokens from contract to buyer
        safeTransferFrom(address(this), msg.sender, sale.tokenId, sale.amount, "");

