        Sale storage sale = sales[saleId];
        require(sale.active, "Sale is not active");
        require(sale.seller == msg.sender, "Only the seller can cancel the sale");

        // Transfer tokens back to seller
        safeTransferFrom(address(this), msg.sender, sale.tokenId, sale.amount, "");

        sale.active = false; // Mark sale as inactive

        emit SaleCancelled(saleId);
    }

    // --- Admin Functions ---

    function setBaseURI(string memory baseURI_) public onlyOwner {
        _setBaseURI(baseURI_);
    }

    // --- Fallback Function ---
    receive() external payable {}
    fallback() external payable {}
}

