import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/math/SafeMath.sol";

contract LiquidStaking is ERC20, Ownable {
    using SafeMath for uint256;

    IERC20 public immutable underlyingToken;
    mapping(address => uint256) public stakedAmounts;
    uint256 public totalStaked;

    event Staked(address indexed staker, uint256 amount);
    event Unstaked(address indexed staker, uint256 amount);

    constructor(address _underlyingTokenAddress, string memory name_, string memory symbol_) ERC20(name_, symbol_) {
        underlyingToken = IERC20(_underlyingTokenAddress);
    }

    function stake(uint256 _amount) external {
        require(_amount > 0, "Amount must be greater than 0");
        require(underlyingToken.balanceOf(msg.sender) >= _amount, "Insufficient balance");

        // Check return value of transferFrom
        require(underlyingToken.transferFrom(msg.sender, address(this), _amount), "transferFrom failed");

        stakedAmounts[msg.sender] = stakedAmounts[msg.sender].add(_amount);
        totalStaked = totalStaked.add(_amount);

        _mint(msg.sender, _amount); // Mint stToken to the staker

        emit Staked(msg.sender, _amount);
    }

    function unstake(uint256 _amount) external {
        require(_amount > 0, "Amount must be greater than 0");
        require(balanceOf(msg.sender) >= _amount, "Insufficient stToken balance");

        uint256 actualUnstakeAmount = _amount;
        // In a more complex scenario, you might adjust the unstake amount based on a redemption rate
        // For this basic example, 1 stToken = 1 underlying token equivalent.

        stakedAmounts[msg.sender] = stakedAmounts[msg.sender].sub(_amount);
        totalStaked = totalStaked.sub(_amount);

        _burn(msg.sender, _amount); // Burn stToken from the staker

        require(underlyingToken.balanceOf(address(this)) >= actualUnstakeAmount, "Insufficient underlying tokens in contract");

        // Check return value of transfer
        require(underlyingToken.transfer(msg.sender, actualUnstakeAmount), "transfer failed");

        emit Unstaked(msg.sender, actualUnstakeAmount);
    }

    function getStakedBalance(address _user) external view returns (uint256) {
        return stakedAmounts[_user];
    }

    function getStTokenBalance(address _user) external view returns (uint256) {
        return balanceOf(_user);
    }

    function getUnderlyingToken() external view returns (address) {
        return address(underlyingToken);
    }

    function getTotalStaked() external view returns (uint256) {
        return totalStaked;
    }

    // Optional: Add functions for rewards distribution, governance, etc.
    // This contract assumes a 1:1 redemption for simplicity.
    // A real-world liquid staking solution would involve more complex mechanisms
    // for reward accrual, fee management, and potential slashing.
}

