import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract ConstantProductAMM is ReentrancyGuard {
    IERC20 public token0;
    IERC20 public token1;

    uint256 public invariant; // k = reserves0 * reserves1

    mapping(address => uint256) public reserves0;
    mapping(address => uint256) public reserves1;

    mapping(address => uint256) public liquidity;

    event Swap(address indexed sender, uint256 amount0In, uint256 amount1In, uint256 amount0Out, uint256 amount1Out);
    event AddLiquidity(address indexed provider, uint256 amount0, uint256 amount1, uint256 liquidityMinted);
    event RemoveLiquidity(address indexed provider, uint256 amount0, uint256 amount1, uint256 liquidityBurned);

    constructor(address _token0, address _token1) {
        token0 = IERC20(_token0);
        token1 = IERC20(_token1);
    }

    function getReserves() public view returns (uint256 _reserve0, uint256 _reserve1) {
        _reserve0 = reserves0[address(this)];
        _reserve1 = reserves1[address(this)];
    }

    function setInvariant() internal {
        (uint256 _reserve0, uint256 _reserve1) = getReserves();
        invariant = _reserve0 * _reserve1;
    }

    function addLiquidity(uint256 amount0Desired, uint256 amount1Desired) public {
        (uint256 _reserve0, uint256 _reserve1) = getReserves();

        require(amount0Desired > 0 || amount1Desired > 0, "Cannot add zero liquidity");

        uint256 amount0;
        uint256 amount1;

        if (_reserve0 == 0 && _reserve1 == 0) {
            amount0 = amount0Desired;
            amount1 = amount1Desired;
            require(token0.transferFrom(msg.sender, address(this), amount0), "Transfer failed");
            require(token1.transferFrom(msg.sender, address(this), amount1), "Transfer failed");
            setInvariant(); // Initialize invariant with the first liquidity added
        } else {
            uint256 amount0Optimal = (amount1Desired * _reserve0) / _reserve1;
            uint256 amount1Optimal = (amount0Desired * _reserve1) / _reserve0;

            if (amount0Optimal <= amount0Desired && amount1Optimal <= amount1Desired) {
                amount0 = amount0Desired;
                amount1 = amount1Desired;
            } else if (amount0Optimal < amount0Desired) {
                amount0 = amount0Optimal;
                amount1 = (amount0 * _reserve1) / _reserve0;
            } else {
                amount1 = amount1Optimal;
                amount0 = (amount1 * _reserve0) / _reserve1;
            }
            require(token0.transferFrom(msg.sender, address(this), amount0), "Transfer failed");
            require(token1.transferFrom(msg.sender, address(this), amount1), "Transfer failed");
            setInvariant(); // Update invariant
        }

        // Mint liquidity tokens
        uint256 totalLiquidity = liquidity[address(this)];
        uint256 liquidityMinted = 0;
        if (totalLiquidity == 0) {
            liquidityMinted = amount0 + amount1; // Initial liquidity
        } else {
            liquidityMinted = (amount0 * totalLiquidity) / _reserve0; // Proportional to token0
        }
        liquidity[msg.sender] += liquidityMinted;

        emit AddLiquidity(msg.sender, amount0, amount1, liquidityMinted);
    }

    function removeLiquidity(uint256 amount0Min, uint256 amount1Min) public nonReentrant {
        (uint256 _reserve0, uint256 _reserve1) = getReserves();
        uint256 _liquidity = liquidity[msg.sender];
        require(_liquidity > 0, "No liquidity to remove");

        uint256 amount0 = (_reserve0 * _liquidity) / invariant;
        uint256 amount1 = (_reserve1 * _liquidity) / invariant;

        require(amount0 >= amount0Min, "Insufficient amount0");
        require(amount1 >= amount1Min, "Insufficient amount1");

        liquidity[msg.sender] -= _liquidity;
        reserves0[address(this)] -= amount0;
        reserves1[address(this)] -= amount1;
        setInvariant(); // Update invariant

        require(token0.transfer(msg.sender, amount0), "Transfer failed");
        require(token1.transfer(msg.sender, amount1), "Transfer failed");

        emit RemoveLiquidity(msg.sender, amount0, amount1, _liquidity);
    }

    function swapExactTokensForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address to,
        bool isToken0Input
    ) public nonReentrant {
        (uint256 _reserve0, uint256 _reserve1) = getReserves();
        uint256 amount0In = 0;
        uint256 amount1In = 0;
        uint256 amount0Out = 0;
        uint256 amount1Out = 0;

        if (isToken0Input) {
            amount0In = amountIn;
            require(token0.transferFrom(msg.sender, address(this), amount0In), "Transfer failed");
            amount1Out = (_reserve1 * amount0In) / (_reserve0 + amount0In);
            require(amount1Out >= amountOutMin, "Insufficient amount1 out");
            reserves0[address(this)] += amount0In;
            reserves1[address(this)] -= amount1Out;
        } else {
            amount1In = amountIn;
            require(token1.transferFrom(msg.sender, address(this), amount1In), "Transfer failed");
            amount0Out = (_reserve0 * amount1In) / (_reserve1 + amount1In);
            require(amount0Out >= amountOutMin, "Insufficient amount0 out");
            reserves1[address(this)] += amount1In;
            reserves0[address(this)] -= amount0Out;
        }

        setInvariant(); // Update invariant

        if (isToken0Input) {
            require(token1.transfer(to, amount1Out), "Transfer failed");
        } else {
            require(token0.transfer(to, amount0Out), "Transfer failed");
        }

        emit Swap(msg.sender, amount0In, amount1In, amount0Out, amount1Out);
    }

    function getAmountOut(uint256 amountIn, bool isToken0Input) public view returns (uint256) {
        (uint256 _reserve0, uint256 _reserve1) = getReserves();
        if (isToken0Input) {
            return (_reserve1 * amountIn) / (_reserve0 + amountIn);
        } else {
            return (_reserve0 * amountIn) / (_reserve1 + amountIn);
        }
    }

    function getAmountIn(uint256 amountOut, bool isToken0Output) public view returns (uint256) {
        (uint256 _reserve0, uint256 _reserve1) = getReserves();
        if (isToken0Output) {
            return (_reserve1 * amountOut) / (_reserve0 - amountOut);
        } else {
            return (_reserve0 * amountOut) / (_reserve1 - amountOut);
        }
    }
}

