interface IStrategy {
    function deposit(uint256 _amount) external;
    function withdraw(uint256 _amount) external;
    function harvest() external returns (uint256 _earned);
    function withdrawAll() external returns (uint256 _balance);
    function getBalance() external view returns (uint256 _balance);
    function getRewardToken() external view returns (IERC20 _rewardToken);
}

contract YieldAggregatorVault is Ownable {
    using SafeMath for uint256;

    IERC20 public depositToken;
    IStrategy public strategy;

    uint256 public totalAssets; // Total amount of depositToken held by the vault (including staked in strategy)
    uint256 public totalShares; // Total shares minted to users

    uint256 public depositFeeBPS; // Deposit fee in basis points (e.g., 100 for 1%)
    uint256 public withdrawalFeeBPS; // Withdrawal fee in basis points (e.g., 50 for 0.5%)
    uint256 public managementFeeBPS; // Management fee in basis points (e.g., 200 for 2%)

    mapping(address => uint256) public balanceOfShares; // User's shares

    // Reentrancy guard
    bool private _notEntered;

    modifier nonReentrant() {
        require(_notEntered, "Reentrant call");
        _notEntered = false;
        _;
        _notEntered = true;
    }

    event Deposit(address indexed user, uint256 amount, uint256 shares);
    event Withdraw(address indexed user, uint256 amount, uint256 shares);
    event StrategyHarvested(uint256 harvestedAmount);
    event FeesUpdated(uint256 depositFeeBPS, uint256 withdrawalFeeBPS, uint256 managementFeeBPS);
    event StrategySet(address indexed newStrategy);

    constructor(
        address _depositTokenAddress,
        address _strategyAddress,
        uint256 _depositFeeBPS,
        uint256 _withdrawalFeeBPS,
        uint256 _managementFeeBPS
    ) {
        depositToken = IERC20(_depositTokenAddress);
        strategy = IStrategy(_strategyAddress);
        depositFeeBPS = _depositFeeBPS;
        withdrawalFeeBPS = _withdrawalFeeBPS;
        managementFeeBPS = _managementFeeBPS;
        _notEntered = true; // Initialize reentrancy guard
    }

    function setStrategy(address _newStrategyAddress) public onlyOwner nonReentrant {
        require(_newStrategyAddress != address(0), "Invalid strategy address");

        // Withdraw all assets from the current strategy
        uint256 balanceToWithdraw = strategy.getBalance();
        if (balanceToWithdraw > 0) {
            strategy.withdrawAll();
            totalAssets = totalAssets.sub(balanceToWithdraw); // Update totalAssets before changing strategy
        }

        strategy = IStrategy(_newStrategyAddress);
        emit StrategySet(_newStrategyAddress);
    }

    function setFees(uint256 _depositFeeBPS, uint256 _withdrawalFeeBPS, uint256 _managementFeeBPS) public onlyOwner {
        depositFeeBPS = _depositFeeBPS;
        withdrawalFeeBPS = _withdrawalFeeBPS;
        managementFeeBPS = _managementFeeBPS;
        emit FeesUpdated(_depositFeeBPS, _withdrawalFeeBPS, _managementFeeBPS);
    }

    function deposit(uint256 _amount) public nonReentrant {
        require(_amount > 0, "Amount must be greater than zero");

        // Calculate and apply deposit fee
        uint256 feeAmount = _amount.mul(depositFeeBPS).div(10000);
        uint256 netAmount = _amount.sub(feeAmount);

        // Transfer tokens from user to vault
        require(depositToken.transferFrom(msg.sender, address(this), _amount), "Token transfer failed");

        // Add net amount to total assets
        totalAssets = totalAssets.add(netAmount);

        // Calculate shares based on vault's value
        uint256 shares = 0;
        // Use `totalShares == 0` which is fine for checking initial state.
        if (totalShares == 0) {
            shares = netAmount; // First depositor gets shares equal to their net deposit
        } else {
            // Perform multiplication before division to maintain precision
            shares = netAmount.mul(totalShares).div(totalAssets.sub(netAmount));
        }

        balanceOfShares[msg.sender] = balanceOfShares[msg.sender].add(shares);
        totalShares = totalShares.add(shares);

        emit Deposit(msg.sender, _amount, shares);
    }

    function withdraw(uint256 _shares) public nonReentrant {
        require(_shares > 0, "Shares must be greater than zero");

        uint256 userShares = balanceOfShares[msg.sender];
        require(_shares <= userShares, "Insufficient shares");

        // Calculate amount to withdraw based on shares. Perform multiplication before division.
        uint256 amountToWithdraw = _shares.mul(totalAssets).div(totalShares);
        require(amountToWithdraw > 0, "Calculated amount is zero");

        // Calculate and apply withdrawal fee
        uint256 feeAmount = amountToWithdraw.mul(withdrawalFeeBPS).div(10000);
        uint256 netAmountToWithdraw = amountToWithdraw.sub(feeAmount);

        // Update user's shares and total shares
        balanceOfShares[msg.sender] = userShares.sub(_shares);
        totalShares = totalShares.sub(_shares);

        // Update total assets in the vault
        totalAssets = totalAssets.sub(amountToWithdraw);

        // Transfer tokens to user
        require(depositToken.transfer(msg.sender, netAmountToWithdraw), "Token transfer failed");

        emit Withdraw(msg.sender, netAmountToWithdraw, _shares);
    }

    function withdrawAll() public nonReentrant {
        uint256 sharesToWithdraw = balanceOfShares[msg.sender];
        require(sharesToWithdraw > 0, "No shares to withdraw");
        withdraw(sharesToWithdraw);
    }

    function harvest() public onlyOwner nonReentrant {
        // Harvest rewards from the strategy
        uint256 earnedRewards = strategy.harvest();
        require(earnedRewards > 0, "No rewards earned");

        // Calculate management fee
        uint256 managementFee = earnedRewards.mul(managementFeeBPS).div(10000);
        uint256 netRewards = earnedRewards.sub(managementFee);

        // Add net rewards to total assets
        totalAssets = totalAssets.add(netRewards);

        // Transfer management fee to the owner
        require(depositToken.transfer(owner(), managementFee), "Management fee transfer failed");

        emit StrategyHarvested(earnedRewards);
    }

    function invest() public onlyOwner nonReentrant {
        uint256 vaultBalance = depositToken.balanceOf(address(this));

        if (vaultBalance > 0) {
            strategy.deposit(vaultBalance);
            totalAssets = totalAssets.add(vaultBalance); // Update totalAssets after depositing to strategy
        }
    }

    function rebalanceStrategy() public onlyOwner nonReentrant {
        // Withdraw all from strategy
        uint256 balanceInStrategy = strategy.withdrawAll(); // Capture return value
        totalAssets = totalAssets.sub(balanceInStrategy); // Deduct from totalAssets as it's now in vault

        // Re-deposit into the strategy
        uint256 vaultBalance = depositToken.balanceOf(address(this));
        if (vaultBalance > 0) {
            strategy.deposit(vaultBalance);
            totalAssets = totalAssets.add(vaultBalance); // Add back to totalAssets as it's in strategy
        }
    }

    function getVaultInfo()
        public
        view
        returns (
            uint256 _totalAssets,
            uint256 _totalShares,
            uint256 _depositFeeBPS,
            uint256 _withdrawalFeeBPS,
            uint256 _managementFeeBPS,
            address _depositToken,
            address _strategy
        )
    {
        return (
            totalAssets,
            totalShares,
            depositFeeBPS,
            withdrawalFeeBPS,
            managementFeeBPS,
            address(depositToken),
            address(strategy)
        );
    }

    function getUserInfo(address _user)
        public
        view
        returns (uint256 _balanceOfShares, uint256 _balanceInDepositToken)
    {
        uint256 shares = balanceOfShares[_user];
        uint256 balance = 0;
        if (totalShares > 0) {
            balance = shares.mul(totalAssets).div(totalShares);
        }
        return (shares, balance);
    }

    // Function to allow owner to withdraw any accidental sends to the vault contract
    function withdrawERC20(address _tokenAddress, uint256 _amount) public onlyOwner {
        IERC20 token = IERC20(_tokenAddress);
        require(token.balanceOf(address(this)) >= _amount, "Insufficient token balance in vault");
        require(token.transfer(owner(), _amount), "Withdraw ERC20 failed");
    }

    // Function to withdraw ETH if it was accidentally sent to the contract
    function withdrawETH(uint256 _amount) public onlyOwner {
        require(address(this).balance >= _amount, "Insufficient ETH balance in vault");
        payable(owner()).transfer(_amount);
    }

    // Fallback function to receive ETH
    receive() external payable {
        // This function is necessary to receive ETH.
        // The deposit and invest functions would need to be adapted if depositToken is ETH.
        // For ERC20 tokens, this function allows receiving stray ETH.
    }
}

