import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract QuadraticVotingDAO is Ownable {
    IERC20 public immutable votingToken;

    struct Proposal {
        uint256 id;
        string description;
        uint256 deadline;
        uint256 yesVotes;
        uint256 noVotes;
        bool executed;
    }

    mapping(uint256 => Proposal) public proposals;
    mapping(uint256 => mapping(address => bool)) private _proposalVotedStatus; // Renamed to avoid conflict
    uint256 public nextProposalId;

    event ProposalCreated(uint256 indexed proposalId, string description, uint256 deadline);
    event Voted(uint256 indexed proposalId, address voter, uint256 votingPower, bool support);
    event ProposalExecuted(uint256 indexed proposalId);

    constructor(address _votingTokenAddress) {
        votingToken = IERC20(_votingTokenAddress);
        nextProposalId = 1;
    }

    function _getVotingPower(address _voter) internal view returns (uint256) {
        uint256 tokenBalance = votingToken.balanceOf(_voter);
        return uint256(sqrt(tokenBalance));
    }

    function sqrt(uint256 _n) internal pure returns (uint256) {
        if (_n == 0) return 0;
        uint256 x = _n / 2 + 1;
        uint256 y = (_n / x + x) / 2;
        while (y < x) {
            x = y;
            y = (_n / x + x) / 2;
        }
        return x;
    }

    function createProposal(string memory _description, uint256 _duration) public onlyOwner {
        uint256 deadline = block.timestamp + _duration;
        proposals[nextProposalId] = Proposal({
            id: nextProposalId,
            description: _description,
            deadline: deadline,
            yesVotes: 0,
            noVotes: 0,
            executed: false
        });
        emit ProposalCreated(nextProposalId, _description, deadline);
        nextProposalId++;
    }

    function vote(uint256 _proposalId, bool _support) public {
        Proposal storage p = proposals[_proposalId];
        require(block.timestamp <= p.deadline, "Proposal has expired");
        require(!_proposalVotedStatus[_proposalId][msg.sender], "You have already voted on this proposal");

        uint256 votingPower = _getVotingPower(msg.sender);
        require(votingPower > 0, "You have no voting power");

        _proposalVotedStatus[_proposalId][msg.sender] = true;

        if (_support) {
            p.yesVotes += votingPower;
        } else {
            p.noVotes += votingPower;
        }

        emit Voted(_proposalId, msg.sender, votingPower, _support);
    }

    function executeProposal(uint256 _proposalId) public onlyOwner {
        Proposal storage p = proposals[_proposalId];
        require(block.timestamp > p.deadline, "Proposal has not yet expired");
        require(!p.executed, "Proposal has already been executed");

        // Define a simple majority threshold, e.g., 50% + 1 vote of total voting power
        // For simplicity here, we'll just check if yesVotes > noVotes.
        // A more robust implementation would involve calculating total voting power.
        require(p.yesVotes > p.noVotes, "Proposal did not pass");

        // In a real DAO, this function would trigger other actions based on the proposal.
        // For this example, we just mark it as executed.
        p.executed = true;
        emit ProposalExecuted(_proposalId);
    }

    function getProposal(uint256 _proposalId) public view returns (
        uint256 id,
        string memory description,
        uint256 deadline,
        uint256 yesVotes,
        uint256 noVotes,
        bool executed
    ) {
        Proposal storage p = proposals[_proposalId];
        return (
            p.id,
            p.description,
            p.deadline,
            p.yesVotes,
            p.noVotes,
            p.executed
        );
    }

    // Renamed this function to avoid conflict with the mapping name
    function hasVoted(uint256 _proposalId, address _voter) public view returns (bool) {
        return _proposalVotedStatus[_proposalId][_voter];
    }
}

