pragma solidity ^0.8.0;

contract SocialRecoveryWallet {
    address public owner;
    mapping(address => bool) public guardians;
    uint256 public recoveryThreshold;
    uint256 public recoverySessionTimeout = 7 days; // Example timeout for recovery sessions

    struct RecoverySession {
        uint256 initiationTimestamp;
        uint256 votesCount;
        mapping(address => bool) hasVoted; // Tracks if a guardian has voted in this session
    }
    mapping(address => RecoverySession) public recoverySessions;

    event GuardianAdded(address indexed guardian);
    event GuardianRemoved(address indexed guardian);
    event RecoveryThresholdChanged(uint256 newThreshold);
    event RecoverySessionInitiated(address indexed proposedOwner, address indexed initiatingGuardian);
    event RecoveryVoteCast(address indexed proposedOwner, address indexed guardian);
    event RecoveryCompleted(address indexed oldOwner, address indexed newOwner);
    event FundsWithdrawn(address indexed to, uint256 amount);
    event RecoverySessionExpired(address indexed proposedOwner);


    modifier onlyOwner() {
        require(msg.sender == owner, "SocialRecoveryWallet: Caller is not the owner");
        _;
    }

    modifier onlyGuardian() {
        require(guardians[msg.sender], "SocialRecoveryWallet: Caller is not a guardian");
        _;
    }

    constructor(address[] memory _initialGuardians, uint256 _recoveryThreshold) {
        owner = msg.sender;
        recoveryThreshold = _recoveryThreshold;

        for (uint i = 0; i < _initialGuardians.length; i++) {
            require(_initialGuardians[i] != address(0), "SocialRecoveryWallet: Invalid guardian address");
            require(_initialGuardians[i] != owner, "SocialRecoveryWallet: Guardian cannot be the owner");
            guardians[_initialGuardians[i]] = true;
        }
        require(_recoveryThreshold > 0, "SocialRecoveryWallet: Recovery threshold must be greater than 0");
        require(_recoveryThreshold <= _initialGuardians.length, "SocialRecoveryWallet: Recovery threshold cannot exceed the number of initial guardians");
    }

    function addGuardian(address _guardian) public onlyOwner {
        require(_guardian != address(0), "SocialRecoveryWallet: Invalid guardian address");
        require(_guardian != owner, "SocialRecoveryWallet: Guardian cannot be the owner");
        require(!guardians[_guardian], "SocialRecoveryWallet: Guardian already exists");
        guardians[_guardian] = true;
        emit GuardianAdded(_guardian);
    }

    function removeGuardian(address _guardian) public onlyOwner {
        require(guardians[_guardian], "SocialRecoveryWallet: Guardian does not exist");
        require(_guardian != owner, "SocialRecoveryWallet: Cannot remove the owner as a guardian");
        guardians[_guardian] = false;
        emit GuardianRemoved(_guardian);
    }

    function changeRecoveryThreshold(uint256 _newThreshold) public onlyOwner {
        require(_newThreshold > 0, "SocialRecoveryWallet: Threshold must be greater than 0");
        // Optionally, add a check that the new threshold does not exceed the current number of guardians.
        // This requires knowing the current number of guardians, which is not directly tracked here.
        // A more robust implementation might maintain a list of active guardians.
        recoveryThreshold = _newThreshold;
        emit RecoveryThresholdChanged(_newThreshold);
    }

    function changeRecoverySessionTimeout(uint256 _newTimeout) public onlyOwner {
        require(_newTimeout > 0, "SocialRecoveryWallet: Timeout must be greater than 0");
        recoverySessionTimeout = _newTimeout;
    }

    function initiateRecovery(address _proposedOwner) public onlyGuardian {
        require(_proposedOwner != address(0), "SocialRecoveryWallet: Invalid proposed owner address");
        require(_proposedOwner != owner, "SocialRecoveryWallet: Cannot recover to the current owner");
        require(recoverySessions[_proposedOwner].initiationTimestamp == 0, "SocialRecoveryWallet: Recovery session already active for this proposed owner");
        // Guardian cannot initiate recovery for themselves. This implies the guardian is not the proposed owner.
        require(msg.sender != _proposedOwner, "SocialRecoveryWallet: Guardian cannot initiate recovery for themselves");


        // Start a new recovery session
        RecoverySession storage session = recoverySessions[_proposedOwner];
        session.initiationTimestamp = block.timestamp;
        session.votesCount = 1; // The initiating guardian's vote
        session.hasVoted[msg.sender] = true;

        emit RecoverySessionInitiated(_proposedOwner, msg.sender);
    }

    function castRecoveryVote(address _proposedOwner) public onlyGuardian {
        require(_proposedOwner != address(0), "SocialRecoveryWallet: Invalid proposed owner address");
        require(recoverySessions[_proposedOwner].initiationTimestamp > 0, "SocialRecoveryWallet: No active recovery session for this proposed owner");
        require(block.timestamp < recoverySessions[_proposedOwner].initiationTimestamp + recoverySessionTimeout, "SocialRecoveryWallet: Recovery session has expired");
        require(!recoverySessions[_proposedOwner].hasVoted[msg.sender], "SocialRecoveryWallet: Guardian has already voted in this session");

        // Cast the vote
        RecoverySession storage session = recoverySessions[_proposedOwner];
        session.votesCount++;
        session.hasVoted[msg.sender] = true;

        emit RecoveryVoteCast(_proposedOwner, msg.sender);
    }

    function completeRecovery(address _proposedOwner) public {
        require(_proposedOwner != address(0), "SocialRecoveryWallet: Invalid proposed owner address");
        require(recoverySessions[_proposedOwner].initiationTimestamp > 0, "SocialRecoveryWallet: No active recovery session for this proposed owner");
        require(block.timestamp < recoverySessions[_proposedOwner].initiationTimestamp + recoverySessionTimeout, "SocialRecoveryWallet: Recovery session has expired");

        RecoverySession storage session = recoverySessions[_proposedOwner];

        // Check if the threshold is met.
        // The `recoveryThreshold` is an absolute number of votes required.
        // This logic assumes that the owner sets `recoveryThreshold` appropriately
        // relative to the expected number of active guardians.
        if (session.votesCount >= recoveryThreshold) {
            address oldOwner = owner;
            owner = _proposedOwner;
            // Clean up the recovery session state
            delete recoverySessions[_proposedOwner];
            emit RecoveryCompleted(oldOwner, _proposedOwner);
        }
    }

    // Function to cancel an expired recovery session (optional)
    function cancelExpiredRecovery(address _proposedOwner) public {
        require(recoverySessions[_proposedOwner].initiationTimestamp > 0, "SocialRecoveryWallet: No active recovery session for this proposed owner");
        require(block.timestamp >= recoverySessions[_proposedOwner].initiationTimestamp + recoverySessionTimeout, "SocialRecoveryWallet: Recovery session has not expired");

        delete recoverySessions[_proposedOwner];
        emit RecoverySessionExpired(_proposedOwner);
    }


    // Fallback function to receive Ether
    receive() external payable {
        emit FundsWithdrawn(msg.sender, msg.value);
    }

    // Function to withdraw Ether
    function withdraw(address payable _to, uint256 _amount) public onlyOwner {
        require(_to != address(0), "SocialRecoveryWallet: Invalid withdrawal address");
        require(_amount > 0, "SocialRecoveryWallet: Withdrawal amount must be greater than 0");
        require(address(this).balance >= _amount, "SocialRecoveryWallet: Insufficient balance");

        (bool success, ) = _to.call{value: _amount}("");
        require(success, "SocialRecoveryWallet: Ether withdrawal failed");

        emit FundsWithdrawn(_to, _amount);
    }
}
